I18N.pat([
 [/^CS(\d+) で (.+)$/,(m,n,d)=>`at CS${n}: ${I18N.t(d)}`],
 [/^朝の打ち合わせ: 今日は「(.+?)」で。(.*)$/,(m,s,x)=>`Morning briefing: today we go “${I18N.t(s)}”. `+I18N.t(x)],
 [/^夕方の話し合い: 明日は「(.+?)」の予定。(.*)$/,(m,s,x)=>`Evening debrief: tomorrow's plan is “${I18N.t(s)}”. `+I18N.t(x)],
 [/^臨機応変: (.*?)ここからは「(.+?)」で行きます \(電池 (\d+) %\)。$/,(m,w,s,b)=>`Adaptive: ${w? I18N.t(w)+" ":""}From here we go “${I18N.t(s)}” (battery ${b} %).`],
 [/^ドライバー (.+)$/,(m,n)=>"Driver "+I18N.t(n)],
 [/^朝 (\d+) % → 夕方 (.+?) % → 今 (\d+) %$/,"Morning $1 % → evening $2 % → now $3 %"],
 [/^([+−-]?\d+) km \(見込み (\d+) km\)$/,"$1 km (est. $2 km)"],
 [/^([+−±])(\d+) %(・後半は快晴の見込み)?$/,(m,s,a,b)=>`${s}${a} %`+(b?" · clear later":"")],
 [/^巡航 (\d+) km\/h・電池の最小 (\d+) %・ゴール (.+)$/,(m,v,b,g)=>`Cruise ${v} km/h · min battery ${b} % · finish ${g==="届かない見込み"?"not expected":I18N.t(g)}`],
 [/^選んだ走り方は推奨速度と無線の速度指示に使います。% は電池を残す量 \(普通に対して\)、km は(明日|今日)行けそうな位置。$/,(m,d)=>`The chosen plan sets the recommended pace and radio speed orders. % is the battery reserve (vs. Normal); km is how far we can get ${d==="明日"?"tomorrow":"today"}.`],
 [/^最初に乗る人$/,"First driver"],[/^交代する CS \((明日|今日)の見込みの範囲\)$/,(m,d)=>`Change at CS (within ${d==="明日"?"tomorrow":"today"}'s estimate)`],
 [/^(\d+) km・(.+?) Wh\/km$/,"$1 km · $2 Wh/km"],
 [/^(\d+) 回・A (\d+)・C (\d+)$/,"$1 times · A $2 · C $3"],[/^(\d+) チーム$/,"$1 teams"],
 [/^明日 \(Day(\d)\) の日射予報$/,"Tomorrow's (Day $1) irradiance forecast"],
 [/^約 (.+?) kWh \(\+(\d+) %\)$/,"about $1 kWh (+$2 %)"],[/^約 (\d+) %$/,"about $1 %"],[/^(.+?) ごろ$/,"around $1"],
 [/^グリッドは P(.+?)。最初の CS は (.+?) です。$/,"We're on grid P$1. The first CS is $2."],
 [/^電池は今 (\d+) % です。$/,"Battery is at $1 % now."],[/^電池は (\d+) % です。$/,"Battery is at $1 %."],
 [/^昨日は (\d+) km。(.*)$/,(m,k,x)=>`Yesterday: ${k} km. `+I18N.t(x)],[/^今日は (\d+) km。(.*)$/,(m,k,x)=>`Today: ${k} km. `+I18N.t(x)],
 [/^見込みより (\d+) km (先|手前)でした。$/,(m,k,w)=>`${k} km ${w==="先"?"further":"short of"} the estimate.`],[/^見込みより (\d+) km (先|手前)です。$/,(m,k,w)=>`${k} km ${w==="先"?"further":"short of"} the estimate.`],
 [/^朝の充電で電池は (\d+) % まで戻っています。$/,"The morning charge brought the battery back to $1 %."],
 [/^今日の日射は晴れの日の約 (\d+) %。(.*)$/,(m,a,b)=>`Today's sun is about ${a} % of a clear day. `+I18N.t(b)],
 [/^この先では Day(\d) が一番弱くて約 (\d+) %。(.*)$/,(m,d,k,x)=>`Ahead, Day ${d} is the weakest at about ${k} %. `+I18N.t(x)],
 [/^おすすめは「(.+?)」。今日は (\d+) km あたりまで行けそうです。$/,(m,s,k)=>`I recommend “${I18N.t(s)}”. We should reach about ${k} km today.`],
 [/^最初は (.+?) で。交代する CS を決めておこう。$/,(m,n)=>`${I18N.t(n)} first. Let's pick the change CSs.`],
 [/^了解です。今日は CS(\d+) まで見込みですね。$/,"Got it. We expect to reach CS$1 today."],
 [/^発電 (.+?) kWh、消費 (.+?) kWh。電池は (\d+) % です。$/,"Solar $1 kWh, used $2 kWh. Battery at $3 %."],
 [/^電費は (.+?) が一番良くて (.+?) Wh\/km でした。$/,(m,n,w)=>`${I18N.t(n)} had the best efficiency at ${w} Wh/km.`],
 [/^今日は (.+?) Wh\/km で走れました。$/,"We managed $1 Wh/km today."],
 [/^今は P(\d+) \/ (\d+)。(.*)$/,(m,a,b,x)=>`We're P${a} / ${b}. `+I18N.t(x)],
 [/^前の (.+?) とは (.+?) km。$/,"$1 is $2 km ahead."],
 [/^後ろの (.+?) が近い。明日の朝は気を抜かずに行こう。$/,"$1 behind is close. Stay sharp tomorrow morning."],
 [/^明日の日射予報は約 (\d+) %。(.*)$/,(m,k,x)=>`Tomorrow's sun forecast is about ${k} %. `+I18N.t(x)],
 [/^19:15 に電池を切り離します。朝の充電で約 (.+?) kWh 戻る見込みです。$/,"We disconnect the battery at 19:15. The morning charge should add about $1 kWh."],
 [/^朝は (\d+)° で傾けます。夜露でパネルが濡れたら拭きます。$/,"We'll tilt at $1° in the morning and wipe off any dew."],
 [/^明日は (.*?)発進。7:00 に打ち合わせ、7:50 から乗り込み。今日はしっかり休もう。$/,(m,t)=>`Tomorrow we start ${t==="8:00 に"?"at 8:00":I18N.t(t)}. Briefing at 7:00, boarding from 7:50. Rest well tonight.`],
 [/^CS(\d+) で見直し。$/,"Reviewing at CS$1."],
 [/^CS(\d+): 朝の打ち合わせどおり、ここで (.+?) に交代。$/,(m,n,d)=>`CS${n}: as planned this morning, ${I18N.t(d)} takes over here.`],
 [/^CS(\d+) (.+?) \((\d+) km 先\)$/,"CS$1 $2 ($3 km ahead)"],
]);
